package com.insight.quantlife.tests;
import android.app.*;import android.app.job.JobScheduler;import android.database.sqlite.SQLiteDatabase;import android.os.*;import com.insight.quantlife.*;import org.json.*;

public class InformationUiTest extends DocumentEditorTest {
 JSONObject fixture(int i,String type)throws Exception{
  String note="具体知识要领"+i+"：先确认条件，再选择方案。",date="2026-10-"+String.format(java.util.Locale.ROOT,"%02d",28+i%3);JSONArray units=new JSONArray();for(int k=0;k<1+i%5;k++)units.put(new JSONObject().put("text","独立要点"+k).put("sources",new JSONArray().put(new JSONObject().put("start",0).put("end",note.length()).put("quote",note))));
  return new JSONObject().put("id","load-"+type+"-"+i).put("type",type).put("date",date).put("occurredAt",date+"T10:00:00").put("title","批量测试"+i).put("note",note).put("tags",new JSONArray()).put("durationMinutes",type.equals("learning")?30:0).put("platform","本地").put("contentType","article").put("createdAt",i).put("updatedAt",100).put("informationUnits",new JSONObject().put("schemaVersion",InformationUnits.VERSION).put("model","deepseek-flash").put("provider",InformationUnits.PROVIDER).put("unitRule",InformationUnits.RULE).put("complete",true).put("sourceVersion",100).put("sourceHash",QwenLabels.hash(new JSONObject().put("note",note))).put("analyzedAt",100).put("characters",InformationUnits.characters(note)).put("count",units.length()).put("density",units.length()*1000.0/InformationUnits.characters(note)).put("units",units));
 }
 void populate()throws Exception{
  try(SQLiteDatabase db=SQLiteDatabase.openDatabase(getTargetContext().getDatabasePath("quantlife.db").getPath(),null,SQLiteDatabase.OPEN_READWRITE)){
   db.beginTransaction();try{db.delete("records",null,null);for(String type:new String[]{"learning","work_note","idea","experience"})for(int i=0;i<173;i++){JSONObject r=fixture(i,type);if(type.equals("work_note"))r.put("date","2026-10-30");db.execSQL("INSERT INTO records(id,type,date,title,platform,payload) VALUES(?,?,?,?,?,?)",new Object[]{r.getString("id"),r.getString("type"),r.getString("date"),r.getString("title"),r.getString("platform"),r.toString()});}db.setTransactionSuccessful();}finally{db.endTransaction();}
  }
 }
 void checks()throws Exception{
  h=new MainHost(this);h.open();runOnMainSync(()->h.activity.finish());getTargetContext().getSystemService(JobScheduler.class).cancel(7305);populate();h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");
  click("[data-page=records]");check(h.js("document.querySelectorAll('[data-record-list=learning] .record').length===20").equals("true"),"Learning first paint has 20 of 173 records");check(h.js("document.body.innerText.includes('173 条')").equals("true"),"All-record count survives batched rendering");
  h.js("window.__first=document.querySelector('[data-record-list=learning] .record');document.querySelector('[data-record-list=learning] .record-list-footer').scrollIntoView()");until("document.querySelectorAll('[data-record-list=learning] .record').length===40");check(h.js("__first===document.querySelector('[data-record-list=learning] .record')&&new Set([...document.querySelectorAll('[data-record-list=learning] [data-record]')].map(b=>b.dataset.record)).size===40").equals("true"),"Scroll appends 20 unique rows and retains existing DOM");
  h.js("document.querySelector('[data-load-records]').click()");check(h.js("document.querySelectorAll('[data-record-list=learning] .record').length===60").equals("true"),"Load-more fallback appends next batch");
  click("[data-record-list=learning] .record:last-child");until("!!document.querySelector('#doc-flow')");check(h.js("document.querySelector('#doc-flow').innerText.includes('具体知识要领')").equals("true"),"Newly appended row opens its complete original text");close();check(h.js("document.querySelectorAll('[data-record-list=learning] .record').length===60").equals("true"),"Returning from reader retains loaded batches");
  h.js("document.querySelector('#learning-search').value='具体知识要领0：';document.querySelector('#learning-search').dispatchEvent(new Event('input'))");check(h.js("document.querySelectorAll('[data-record-list=learning] .record').length===1&&!!document.querySelector('[data-record=load-learning-0]')").equals("true"),"Full-text search finds an unloaded record");
  h.js("document.querySelector('#learning-search').value='';document.querySelector('#learning-search').dispatchEvent(new Event('input'))");check(h.js("document.querySelectorAll('[data-record-list=learning] .record').length===20").equals("true"),"Changed filter resets the batch limit");
  click("[data-record-tab=work]");h.js("WorkCalendar.selectDay('2026-10-30')");check(h.js("document.querySelectorAll('[data-record-list=work] .record').length===20").equals("true"),"Work logs use batched rendering");
  h.js("document.querySelector('[data-record-list=work] [data-load-records]').click()");check(h.js("document.querySelectorAll('[data-record-list=work] .record').length===40").equals("true"),"Work log batch appends correctly");
  click("[data-record-tab=thoughts]");check(h.js("document.querySelectorAll('[data-action=add-thought]').length===1&&!document.querySelector('[data-action=add-idea], [data-action=add-experience], [data-thought-kind]')&&document.body.innerText.includes('346 篇随笔')").equals("true"),"Legacy inspiration and experience appear as one essay collection");check(h.js("document.querySelectorAll('[data-record-list=thoughts] .record').length===20").equals("true"),"Essay first paint is bounded");click("[data-action=add-thought]");until("!!document.querySelector('#doc-body')");check(h.js("document.querySelector('.document-kind').textContent.includes('随笔')").equals("true"),"New essay editor has unified name");close();
  click("[data-record-tab=learning]");click("#topic-entry");click("[data-topic-range=all]");
  check(h.js("document.querySelector('.calendar-coverage').innerText.replace(/\\s/g,'').includes('173/173')&&parseFloat(document.querySelector('.calendar-month-total strong').textContent)===516").equals("true"),"Calendar uses all 173 records regardless of loaded list rows");
  check(h.js("document.querySelectorAll('.calendar-bar-track i').length===3&&!document.querySelector('.information-card,.quant-card')").equals("true"),"Information metrics use one calendar and three daily bars");
  h.js("document.querySelector('#calendar-metric').value='density';document.querySelector('#calendar-metric').dispatchEvent(new Event('change'))");
  check(h.js("document.querySelectorAll('.calendar-bar-track i').length===3&&!document.querySelector('.calendar-trend svg')").equals("true"),"Density remains a bar chart");
  click("[data-calendar-bar]");until("EvidenceDashboard.active()");click("[data-calendar-record]");check(h.js("document.querySelector('#calendar-detail-dialog').open&&document.querySelectorAll('.calendar-units li').length>0&&document.querySelector('.calendar-units blockquote').textContent.includes('\u5177\u4f53\u77e5\u8bc6\u8981\u9886')").equals("true"),"Period drilldown shows individual units and original evidence");
  click("#evidence-day-detail [data-record]");until("!!document.querySelector('#doc-flow')");close();check(h.js("EvidenceDashboard.active()").equals("true"),"Reader back retains its period detail sheet");click("#evidence-day-close");until("!EvidenceDashboard.active()");
  h.js("document.querySelector('#calendar-metric').value='efficiency';document.querySelector('#calendar-metric').dispatchEvent(new Event('change'))");click("[data-calendar-grain=week]");
  check(h.js("document.querySelector('#calendar-metric').value==='efficiency'").equals("true"),"Weekly bars retain the selected metric");
  runOnMainSync(()->h.web.getSettings().setTextZoom(200));Thread.sleep(350);check(h.js("document.documentElement.scrollWidth<=innerWidth+1&&[...document.querySelectorAll('.evidence-calendar button')].every(b=>{const r=b.getBoundingClientRect();return !r.width||r.height>=44&&r.right<=innerWidth+1})").equals("true"),"Large text and batched detail list remain usable");runOnMainSync(()->h.web.getSettings().setTextZoom(100));
  h.js("appBack()");click("[data-action=add-learning]");until("!!document.querySelector('#doc-body')");int count=records().length();input("保存时才分析","只有点击勾确认才会成为正式记录的正文。");Thread.sleep(1100);check(records().length()==count,"Editing/autosaving draft never creates an analyzable record");click("#doc-save");until("document.querySelector('#doc-mode')?.textContent==='编辑'");check(records().length()==count+1,"Checkmark commits exactly one source record for automatic analysis");close();
 }
 @Override public void onStart(){Bundle out=new Bundle();boolean ok=false;try{if(!Build.HARDWARE.matches("ranchu|goldfish"))throw new Exception("Emulator required");checks();ok=true;out.putString("stream","PASS InformationUiTest: "+passed+" checks\n");}catch(Throwable error){out.putString("stream","FAIL InformationUiTest after "+passed+": "+android.util.Log.getStackTraceString(error));}finally{if(h!=null)try{runOnMainSync(()->h.activity.finish());}catch(Exception ignored){}}finish(ok?Activity.RESULT_OK:Activity.RESULT_CANCELED,out);}
}
